WITH department_stats AS (SELECT dept_id, MIN(hire_date) AS min_hire_date, SORT_ARRAY(COLLECT_SET(job_title)) AS job_title_list FROM employees GROUP BY dept_id) SELECT d.id, d.dept_name, d.budget, ds.min_hire_date, ds.job_title_list FROM departments d LEFT OUTER JOIN department_stats ds ON d.id = ds.dept_id ORDER BY d.dept_name
